cat >> tests/messages.rs <<'E'

#[test]
fn max_message_bytes_limits_body_in_utf8_bytes() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({"MaxMessageBytes": 4}));
    send(&mut h, "q", "abcd");
    send(&mut h, "q", "€a");
    assert_eq!(
        h.err(json!({"Command": "SendMessage", "QueueName": "q", "Body": "€ab"})),
        "InvalidParameterValue"
    );
    assert_eq!(counts(&mut h, "q")["Visible"], 2);
}

#[test]
fn max_message_bytes_rule_comes_before_unsupported_operation() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({"MaxMessageBytes": 1}));
    assert_eq!(
        h.err(json!({"Command": "SendMessage", "QueueName": "q", "Body": "ab", "GroupId": "g"})),
        "InvalidParameterValue"
    );
}

#[test]
fn lowering_max_message_bytes_keeps_existing_messages() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({}));
    send(&mut h, "q", "longer body");
    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q",
        "Attributes": {"MaxMessageBytes": 3}}));
    assert_eq!(bodies(&receive(&mut h, "q", 1)), ["longer body"]);
    assert_eq!(
        h.err(json!({"Command": "SendMessage", "QueueName": "q", "Body": "four"})),
        "InvalidParameterValue"
    );
}

#[test]
fn max_message_bytes_does_not_stop_dead_letter_moves() {
    let mut h = Harness::new();
    create(&mut h, "dlq", json!({"MaxMessageBytes": 1}));
    create(
        &mut h,
        "q",
        json!({"DeadLetterQueue": "dlq", "MaxReceiveCount": 1, "VisibilityTimeout": 0}),
    );
    send(&mut h, "q", "long body");
    receive(&mut h, "q", 1);
    assert!(receive(&mut h, "q", 1).is_empty());
    assert_eq!(bodies(&receive(&mut h, "dlq", 1)), ["long body"]);
}
