            assert_eq!(batch_err(&mut h, command, bad.clone()), "InvalidBatchEntryId", "{bad}");
        }
        let code = batch_err(&mut h, command, json!([{"Id": "a"}, {"Id": "a"}]));
        assert_eq!(code, "BatchEntryIdsNotDistinct");
        let code = batch_err(&mut h, command, json!([{"Id": "a"}, {"Id": "A"}, {"Id": "x".repeat(80)}]));
        assert_ne!(code, "BatchEntryIdsNotDistinct");
    }
    assert_eq!(send_batch(&mut h, "q", json!(ten))["Successful"].as_array().unwrap().len(), 10);
    let counts = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}))["Counts"].clone();
    assert_eq!(counts["Visible"], 10);
}

#[test]
fn rules_come_in_the_written_order() {
    let mut h = harness();
    let eleven: Vec<Value> = (0..11).map(|_| json!(1)).collect();
    assert_eq!(batch_err(&mut h, "SendMessageBatch", json!(eleven)), "TooManyEntriesInBatchRequest");
    assert_eq!(batch_err(&mut h, "SendMessageBatch", json!([1, 1])), "InvalidBatchEntryId");
}

#[test]
fn earlier_checks_decide_before_batch_rules() {
    let mut h = harness();
    for command in ["SendMessageBatch", "DeleteMessageBatch"] {
        assert_eq!(h.err(json!({"Command": command, "Entries": []})), "MissingParameter");
        assert_eq!(h.err(json!({"Command": command, "QueueName": "q"})), "MissingParameter");
        assert_eq!(h.err(json!({"Command": command, "QueueName": "q", "Entries": null})), "MissingParameter");
        assert_eq!(h.err(json!({"Command": command, "QueueName": "q", "Entries": {}})), "InvalidParameterValue");
        assert_eq!(h.err(json!({"Command": command, "QueueName": 1, "Entries": []})), "InvalidParameterValue");
        assert_eq!(h.err(json!({"Command": command, "QueueName": "nope", "Entries": []})), "QueueDoesNotExist");
    }
}

#[test]
fn delete_batch_deletes_valid_handles_and_reports_the_rest() {
    let mut h = harness();
    send_batch(&mut h, "q", json!([{"Id": "a", "Body": "1"}, {"Id": "b", "Body": "2"}]));
    let r = h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q", "MaxMessages": 2}));
    let first = r["Messages"][0]["ReceiptHandle"].clone();
    let second = r["Messages"][1]["ReceiptHandle"].clone();
    let r = delete_batch(
        &mut h,
        "q",
        json!([{"Id": "1", "ReceiptHandle": first}, {"Id": "2", "ReceiptHandle": "r-99"},
               {"Id": "3", "ReceiptHandle": first}, {"Id": "4"},
               {"Id": "5", "ReceiptHandle": second}]),
    );
    assert_eq!(r["Successful"], json!([{"Id": "1"}, {"Id": "5"}]));
    let codes: Vec<(&str, &str)> = r["Failed"]
        .as_array()
        .unwrap()
        .iter()
        .map(|f| (f["Id"].as_str().unwrap(), f["error"]["code"].as_str().unwrap()))
        .collect();
    assert_eq!(
        codes,
        [("2", "ReceiptHandleInvalid"), ("3", "ReceiptHandleExpired"), ("4", "MissingParameter")]
    );
    let counts = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}))["Counts"].clone();
    assert_eq!(counts, json!({"Visible": 0, "InFlight": 0, "Delayed": 0}));
}
